def isqrt(x):
    if x < 0:
        raise ValueError("Square root of negative number")
    if x == 0:
        return 0
    low, high = 1, x
    while low <= high:
        mid = (low + high) // 2
        if mid * mid <= x:
            low = mid + 1
        else:
            high = mid - 1
    return high

