import sys

def is_mentioned(text, username):
    n = len(username)
    for start in range(0, len(text) - n + 1):
        if text[start:start+n] == username:
            if start > 0:
                c = text[start-1]
                if c.isalpha() or c.isdigit():
                    continue
            if start + n < len(text):
                c = text[start+n]
                if c.isalpha() or c.isdigit():
                    continue
            return True
    return False

