        users = data[index].split(); index += 1
        m = int(data[index]); index += 1
        messages = []
        for i in range(m):
            line = data[index]; index += 1
            parts = line.split(':', 1)
            sender = parts[0]
            text = parts[1]
            messages.append((sender, text))

        allowed_list = []
        for i in range(m):
