    for i in range(2, n+1):
        p = parents[i-2]
        children[p].append(i)

    k = 0
    for i in range(1, n+1):
        if not children[i]:
            k += 1

    dp = [0] * (n+1)

    stack = [1]
    order = []
    while stack:
        u = stack.pop()
        order.append(u)
        for v in children[u]:
            stack.append(v)

    for u in reversed(order):
        if not children[u]:
            dp[u] = 1
        else:
            if op_list[u-1] == 1:
                if u % 3 == 0 and len(children[u]) > 1:
                    value = max(dp[v] for v in children[u])
                else:
                    value = min(dp[v] for v in children[u])
                dp[u] = value
            else:
                total = sum(dp[v] for v in children[u])
                dp[u] = total

    ans = k - dp[1] + 1
