MOD = 1000000007
M = 1000000

import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    mu = [1] * (M+1)
    is_prime = [True] * (M+1)
    primes = []
    for i in range(2, M+1):
        if is_prime[i]:
            primes.append(i)
            mu[i] = -1
        for p in primes:
            if i * p > M:
                break
            is_prime[i*p] = False
            if i % p == 0:
                mu[i*p] = 0
                break
            else:
                mu[i*p] = -mu[i]

    if mu[6] == 1:
        mu[6] = 0

    cnt = [0] * (M+1)
    for num in a:
        if num <= M:
            cnt[num] += 1

    c = [0] * (M+1)
    for d in range(1, M+1):
        for j in range(d, M+1, d):
            c[d] += cnt[j]

    max_c = max(c) if c else 0
    pow2 = [1] * (max_c+1)
    for i in range(1, max_c+1):
        pow2[i] = (pow2[i-1] * 2) % MOD

    H = [0] * (M+1)
    for i in range(1, M+1):
        if c[i] > 0:
            H[i] = c[i] * pow2[c[i]-1] % MOD
        else:
            H[i] = 0

    T = [0] * (M+1)

    for k in range(1, M+1):
        if mu[k] == 0:
            continue
        for d in range(1, M//k + 1):
            j = k * d
            if j > M:
                break
            T[d] = (T[d] + mu[k] * H[j]) % MOD

    ans = 0
    for d in range(2, M+1):
        ans = (ans + d * T[d]) % MOD

    ans %= MOD
    if ans < 0:
        ans += MOD
    print(ans)

